export default {
  name: "table-column-custom-render",
  functional: true,
  props: {
    row: Object,
    column: Object,
    dataTableRef: Object,  //指向data-table组件实例
    render: Function
  },
  render(h, ctx) {
    const params = {
      row: ctx.props.row,
      column: ctx.props.column,
      dataTableRef: ctx.props.dataTableRef,  //指向data-table组件实例
    }

    return ctx.props.render(h, params)
  }
}
